import numpy as np
k1=np.array([[0,0,3,0],[2,0,3,4],[2,1,1,0],[2,0,0,4]])
o1=np.array([[2,2,2,0],[0,1,0,0],[0,1,3,3],[4,0,4,0]])
k2=np.array([[0,3,1],[4,3,0],[2,0,4]])
o2=np.array([[2,4,0],[0,3,3],[4,0,1]])
for k,o in [(k1,o1),(k2,o2)]:
 for r in range(4):
  x=np.rot90(k,r)
  for f in [False,True]:
   y=np.fliplr(x) if f else x
   if y.shape==o.shape:
    print(r,f,np.array_equal(y,o), 'same occ',np.array_equal(y!=0,o!=0))
